import{c as e,Q as r,j as d,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Auto-load Token 最佳實踐 — 五報告合併綜述 + gap-vote 共識","description":"","frontmatter":{"title":"Auto-load Token 最佳實踐 — 五報告合併綜述 + gap-vote 共識","date":"2026-06-05T00:00:00.000Z","status":"5 份原報告就地更新（append-only 增量段）+ 本合併報告為 SSoT 索引/綜述","branch":"feature/autoload-research-merge-2026-06-05","corpus":"research/papers/ 近期 76 篇 md（2025-06 起，扣已接地 9 篇）","merges":["2026-05-12-best-practices-simplicity.md","2026-05-18-auto-load-token-best-practices.md","2026-06-04-autoload-slimming-feasibility-research.md","2026-06-04-autoload-test-framework-blueprint.md","2026-06-04-autoload-test-gates-execution-report.md"],"method":"gap-vote 三技能共識（research-hub / overnight-research / autoresearch:reason）+ 主對話親自 grep 接地","new_gaps_confirmed":13,"type":"consensus + index (SSoT)"},"headers":[],"relativePath":"research/reports/2026-06-05-autoload-token-best-practices-consensus.md","filePath":"research/reports/2026-06-05-autoload-token-best-practices-consensus.md","lastUpdated":1785909234000}'),o={name:"research/reports/2026-06-05-autoload-token-best-practices-consensus.md"};function s(n,t,i,l,c,h){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="auto-load-token-最佳實踐-—-五報告合併綜述" tabindex="-1">Auto-load Token 最佳實踐 — 五報告合併綜述 <a class="header-anchor" href="#auto-load-token-最佳實踐-—-五報告合併綜述" aria-label="Permalink to &quot;Auto-load Token 最佳實踐 — 五報告合併綜述&quot;">​</a></h1><blockquote><p><strong>定位</strong>：本報告是 5 份 auto-load/token/simplicity 主題報告的 <strong>single source of truth 索引 + 跨報告綜述 + 2026-06-05 gap-vote 共識記錄</strong>。原 5 份報告保留（已就地更新增量段，可追溯）；本報告不取代它們，作為導覽與最新共識入口。 <strong>鐵律遵守</strong>：所有量化主張的 verbatim + 行號接地由<strong>主對話親自 grep 重驗</strong>（subagent verdict 非證據，MEMORY Lesson 2026-06-05-E/B）。</p></blockquote><hr><h2 id="_0-tl-dr" tabindex="-1">0. TL;DR <a class="header-anchor" href="#_0-tl-dr" aria-label="Permalink to &quot;0. TL;DR&quot;">​</a></h2><ul><li><strong>5 份報告已高度成熟</strong>：多份在 2026-06-05 前已多輪 re-check，核心主張（auto-load ≤3,500 token / ≤19,000 byte cap、prompt caching 前綴穩定、大道至簡有下限、測試 gate 三條件全綠）穩定。</li><li><strong>本次新增 13 個 confirmed gap</strong>（gap-vote 2/3 共識 + 主對話親自驗），來自近期 76 篇 corpus 中先前未併入的論文，全數以 append-only 增量段落地對應報告。</li><li><strong>無推翻既有結論</strong>：13 gap 皆為「補強 / 量化接地 / 時間維度延伸」，不改任一報告的核心裁決（優化軸關閉、測試 loop 終態、精簡機會性執行）。</li><li><strong>最高價值的 3 條新洞見</strong>：① tokenizer 變更使 token 門檻失準 → byte cap 設計獲背書；② 自生成 context/skill 反傷（SkillsBench −1.3pp / SkillLearnBench 人寫 74.5% vs 自動 30%）→ 人工 gate 是品質來源；③ Model Drifting → auto-load 規則須隨模型升級重評，不可累加沿用。</li></ul><hr><h2 id="_1-五報告索引-ssot-導覽" tabindex="-1">1. 五報告索引（SSoT 導覽） <a class="header-anchor" href="#_1-五報告索引-ssot-導覽" aria-label="Permalink to &quot;1. 五報告索引（SSoT 導覽）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>報告</th><th>主題</th><th>核心結論</th><th>本次新增 gap</th></tr></thead><tbody><tr><td><code>2026-05-18-auto-load-token-best-practices</code></td><td>auto-load token 上限與控制</td><td>≤3,500 token / 三層載入 / cache 穩定</td><td>7（補充 4–10）</td></tr><tr><td><code>2026-05-12-best-practices-simplicity</code></td><td>大道至簡 / 成本效率</td><td>加法思維是效率陷阱；簡潔有下限</td><td>5（補充 A–D + ACE 佐證）</td></tr><tr><td><code>2026-06-04-autoload-slimming-feasibility-research</code></td><td>精簡可行性</td><td>機械可行、低優先、機會性執行</td><td>2（補充 8.1–8.2）</td></tr><tr><td><code>2026-06-04-autoload-test-framework-blueprint</code></td><td>測試框架藍圖</td><td>只 stage protection；§R re-encode 須 user gate</td><td>3（補充 G-F/G-G/G-H）</td></tr><tr><td><code>2026-06-04-autoload-test-gates-execution-report</code></td><td>測試 gate 執行</td><td>T1/T2/T3 全綠，loop 終止</td><td>1（byte-cap tokenizer 免疫）</td></tr></tbody></table><hr><h2 id="_2-跨報告主軸綜述-四大支柱" tabindex="-1">2. 跨報告主軸綜述（四大支柱） <a class="header-anchor" href="#_2-跨報告主軸綜述-四大支柱" aria-label="Permalink to &quot;2. 跨報告主軸綜述（四大支柱）&quot;">​</a></h2><h3 id="支柱-a-—-prompt-caching-前綴穩定性" tabindex="-1">支柱 A — Prompt Caching / 前綴穩定性 <a class="header-anchor" href="#支柱-a-—-prompt-caching-前綴穩定性" aria-label="Permalink to &quot;支柱 A — Prompt Caching / 前綴穩定性&quot;">​</a></h3><p>5 報告共識 + 本次接地：auto-load（CLAUDE.md + rules）是<strong>靜態前綴</strong>，天然適合 system-prompt-only 快取（78.5% 成本降 / 22.9% TTFT，dont-break-cache 已接地）。反模式：把 <code>currentDate</code>/session-id/mid-session tool-list 變更注入前綴 → cache miss。本次新增 <strong>5 階段 context shaper</strong>（dive-into-CC）定位 auto-load 在「所有 shaper 上游」，前綴 byte × N calls 是控制大小的根本原因。</p><h3 id="支柱-b-—-簡潔-vs-完整的張力-簡潔有下限" tabindex="-1">支柱 B — 簡潔 vs 完整的張力（簡潔有下限） <a class="header-anchor" href="#支柱-b-—-簡潔-vs-完整的張力-簡潔有下限" aria-label="Permalink to &quot;支柱 B — 簡潔 vs 完整的張力（簡潔有下限）&quot;">​</a></h3><p>主軸已從「越簡越好」精化為「<strong>去 redundancy ✅ ≠ 削 domain insight ⚠️</strong>」。本次三篇獨立論文佐證下限：</p><ul><li>ACE：brevity bias drops domain insights（已接地）</li><li>beyond-context-window：35:1 壓縮失 specific facts / nuanced constraints，全文 vs 壓縮差 <strong>33.4–35.2pp</strong>（新）</li><li>when-better-prompts-hurt（已接地）+ prompting-inversion（已接地）：通用「更好」prompt 反傷特定任務</li></ul><p>→ 簡潔下限 = 保留 task-critical heuristics（安全紅線、驗證指令 = TYPE A，不可壓）。</p><h3 id="支柱-c-—-harness-配置-模型-自動化有上限-人工-gate-不可省" tabindex="-1">支柱 C — Harness / 配置 &gt; 模型；自動化有上限，人工 gate 不可省 <a class="header-anchor" href="#支柱-c-—-harness-配置-模型-自動化有上限-人工-gate-不可省" aria-label="Permalink to &quot;支柱 C — Harness / 配置 &gt; 模型；自動化有上限，人工 gate 不可省&quot;">​</a></h3><ul><li>blueprint-first / openai-harness-codex（已接地）：確定性 blueprint + 機械 linter &gt; prompt 措辭。</li><li><strong>本次新增</strong>：SkillsBench（自生成 skill −1.3pp，最佳 2–3 個）+ SkillLearnBench（人寫 74.5% vs 自動 ~30% ceiling）+ AHE（structured observability 使 harness 改進從「手工藝」變「工程」，69.7→77.0%）→ <strong>workspace「人工建 skill + skill-evolution gate + 一次一條 §R + user gate」決策獲多論文背書</strong>。</li></ul><h3 id="支柱-d-—-模型升級的時間維度-新主軸" tabindex="-1">支柱 D — 模型升級的時間維度（新主軸） <a class="header-anchor" href="#支柱-d-—-模型升級的時間維度-新主軸" aria-label="Permalink to &quot;支柱 D — 模型升級的時間維度（新主軸）&quot;">​</a></h3><p>本次浮現的新主軸：auto-load 規則是「為特定模型世代調的 prompt」，<strong>不可假設跨模型/跨版本沿用無損</strong>：</p><ul><li>Model Drifting（PromptBridge）：跨模型沿用 prompt 最壞 −10.77pp（GPT-5→Llama HumanEval）</li><li>tokenizer 變更（Opus 4.7 card）：相同內容 token 數 ×1.0–1.35 → token 門檻失準，<strong>byte cap 免疫</strong></li><li>Overthinking Tax（OckBench）：per-token 費率低 ≠ 總成本低（小模型 57% 更貴）</li></ul><p>→ 行動建議：core.md §Framework Integrity 的「移除後 Claude 在哪犯錯？」應加上「<strong>換模型後此規則是否仍最佳？</strong>」；token 門檻引用須標「依當前 tokenizer」。</p><hr><h2 id="_3-vote-matrix-gap-vote-phase-2-主對話-evidence-audit-phase-3" tabindex="-1">3. Vote-Matrix（gap-vote Phase 2）+ 主對話 Evidence Audit（Phase 3） <a class="header-anchor" href="#_3-vote-matrix-gap-vote-phase-2-主對話-evidence-audit-phase-3" aria-label="Permalink to &quot;3. Vote-Matrix（gap-vote Phase 2）+ 主對話 Evidence Audit（Phase 3）&quot;">​</a></h2><blockquote><p>三技能：research-hub（P，架構）/ overnight-research（A，新能力）/ autoresearch:reason（C，演化）。各 agent 回傳 JSON verdict + verbatim + 行號。<strong>主對話對全部 confirm 候選親 grep 重驗</strong>（不採信 agent verdict）。</p></blockquote><table tabindex="0"><thead><tr><th>Gap</th><th>論文 (arXiv)</th><th>verdict</th><th style="text-align:center;">親驗 verbatim</th><th style="text-align:center;">報告 grep</th><th>落點報告</th></tr></thead><tbody><tr><td>SkillsBench +16.2/−1.3pp, 最佳 2–3</td><td>2602.12670</td><td>confirm</td><td style="text-align:center;">✅ L20</td><td style="text-align:center;">0 hits</td><td>auto-load §3.2</td></tr><tr><td>AHE observability 69.7→77.0%</td><td>2604.25850</td><td>confirm</td><td style="text-align:center;">✅ L24/L163</td><td style="text-align:center;">0 hits</td><td>best-practices D / test-framework G-G</td></tr><tr><td>CC 五階段 context shaper</td><td>2604.14228</td><td>confirm</td><td style="text-align:center;">✅ L99-103</td><td style="text-align:center;">0 hits</td><td>auto-load §6</td></tr><tr><td>back-pressure: success silent</td><td>skill-issue</td><td>confirm</td><td style="text-align:center;">✅ L144/146</td><td style="text-align:center;">0 hits</td><td>auto-load §5</td></tr><tr><td>HARBOR telemetry 讀寫不對稱</td><td>2604.20938</td><td>confirm</td><td style="text-align:center;">✅ L100/126</td><td style="text-align:center;">0 hits</td><td>test-framework G-F</td></tr><tr><td>ETH 138 agentfiles 14-22%</td><td>skill-issue</td><td>confirm†</td><td style="text-align:center;">✅ L64-67</td><td style="text-align:center;">0 hits</td><td>auto-load §3.1</td></tr><tr><td>AgentOpt UCB-E 62-76%</td><td>agentopt</td><td>confirm</td><td style="text-align:center;">✅ L22/100</td><td style="text-align:center;">0 hits</td><td>best-practices A3</td></tr><tr><td>OckBench Overthinking Tax 57%/5.1×</td><td>2511.05722</td><td>confirm</td><td style="text-align:center;">✅ L20/65</td><td style="text-align:center;">0 hits</td><td>best-practices A</td></tr><tr><td>PromptBridge Model Drifting −10.77pp</td><td>2512.01420</td><td>confirm</td><td style="text-align:center;">✅ L22/65</td><td style="text-align:center;">0 hits</td><td>auto-load §6 / slimming 8.2</td></tr><tr><td>SkillLearnBench 人寫74.5 vs 自動30%</td><td>2604.20087</td><td>confirm</td><td style="text-align:center;">✅ L20/46/133</td><td style="text-align:center;">0 hits</td><td>best-practices C / test-framework G-H</td></tr><tr><td>Opus 4.7 tokenizer 1.0-1.35×</td><td>opus-4-7-card</td><td>confirm</td><td style="text-align:center;">✅ L86-87</td><td style="text-align:center;">0 hits</td><td>auto-load §2 / test-gates / slimming</td></tr><tr><td>faulty-memory 顯式 gate consolidation</td><td>2605.12978</td><td>confirm</td><td style="text-align:center;">✅ L27</td><td style="text-align:center;">0 hits</td><td>auto-load §3.3</td></tr><tr><td>35:1 壓縮失 nuanced constraints</td><td>2603.04814</td><td>confirm‡</td><td style="text-align:center;">✅ L91/20</td><td style="text-align:center;">0 hits</td><td>best-practices ACE佐證 / slimming 8.1</td></tr></tbody></table><p>† <strong>ETH 138 agentfiles 同源去重</strong>：與 addyosmani 論文引的 ETH Zurich 是<strong>同一份研究</strong>（success −2-3%/cost +20%/human +4%）。仍是 gap（5 報告先前 grep ETH = 0 hits），但標明同源、skill-issue 獨有「14-22% reasoning overhead」新切面，<strong>不當兩篇獨立論文計數</strong>。</p><p>‡ <strong>35:1 語意去重</strong>：與既有 ACE「brevity bias / 簡潔有下限」是<strong>同一概念點</strong>，但 beyond-context-window 提供獨立論文 + 新量化（35:1 + 33.4-35.2pp + 10-turn break-even）。<strong>掛 ACE 段下作佐證，不開新「發現」條目</strong>。</p><h3 id="evidence-audit-表-主對話親自驗" tabindex="-1">Evidence Audit 表（主對話親自驗） <a class="header-anchor" href="#evidence-audit-表-主對話親自驗" aria-label="Permalink to &quot;Evidence Audit 表（主對話親自驗）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>角色</th><th style="text-align:center;">confirm 候選</th><th>主對話抽驗結果</th></tr></thead><tbody><tr><td>Agent 1</td><td>research-hub (P1 harness/config)</td><td style="text-align:center;">7</td><td>✅ G1-G7 verbatim 全屬實；G8 compilers defer 正確</td></tr><tr><td>Agent 2</td><td>overnight-research (P2 context/memory)</td><td style="text-align:center;">2</td><td>✅ faulty-memory L27 + 35:1 L91 屬實；defer/reject 8 條 scope 判斷正確</td></tr><tr><td>Agent 3</td><td>autoresearch:reason (P3 simplicity/skill)</td><td style="text-align:center;">8</td><td>✅ OckBench/PromptBridge/SkillLearnBench/Opus4.7/HeavySkill/Life-Harness verbatim 全屬實</td></tr></tbody></table><p><strong>全部 confirmed gap 在 5 報告 grep 命中數 = 0</strong> → 真 gap（非已併入）。<strong>全部 verbatim 主對話親自 grep 屬實</strong>（無幻覺數字）。</p><hr><h2 id="_4-defer-reject-ledger-scope-mismatch-不落-5-報告" tabindex="-1">4. Defer / Reject Ledger（scope mismatch，不落 5 報告） <a class="header-anchor" href="#_4-defer-reject-ledger-scope-mismatch-不落-5-報告" aria-label="Permalink to &quot;4. Defer / Reject Ledger（scope mismatch，不落 5 報告）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>論文</th><th>verdict</th><th>原因</th></tr></thead><tbody><tr><td>ACON (2510.00615)</td><td>defer</td><td>mid-session 執行時 working context 壓縮，非 session-start auto-load</td></tr><tr><td>RCR-Router (2508.04903)</td><td>defer</td><td>multi-agent role-conditioned routing，非單 session auto-load</td></tr><tr><td>Recursive LM (2512.24601)</td><td>defer</td><td>REPL-based 長 context scaffold，非 auto-load/MEMORY</td></tr><tr><td>is-grep-all-you-need (2605.15184)</td><td>reject</td><td>檢索策略，非 auto-load/token/caching</td></tr><tr><td>delta-mem (2605.12357)</td><td>reject</td><td>神經架構層 memory，非 harness 層</td></tr><tr><td>agentic-memory-unified (2601.01885)</td><td>reject</td><td>agent RL 訓練框架，非 MEMORY.md 檔管理</td></tr><tr><td>externalization (2604.08224)</td><td>reject</td><td>已在 harness-engineering 報告引；無新量化</td></tr><tr><td>compilers-domain (2603.20075)</td><td>defer</td><td>harness body（−60%/+22%），非 auto-load 範圍</td></tr><tr><td>HeavySkill (2605.02396)</td><td>confirm→best-practices</td><td>弱模型當 synthesizer（已併 best-practices A 附近，作模型選擇校準）</td></tr><tr><td>Life-Harness (2605.22166)</td><td>confirm→未落</td><td>BM25 procedural retrieval（88.5%）—skill 動態交付，scope 偏 harness body，記此 ledger 供未來 harness 報告</td></tr></tbody></table><blockquote><p>HeavySkill / Life-Harness 經親驗 verbatim 屬實但 scope 偏「harness body / 模型選擇」而非 auto-load 核心，未強塞 5 報告（守 R2 不湊量）；記 ledger 供未來 harness-engineering 報告。</p></blockquote><hr><h2 id="_5-方法論誠實校準-守-r12-fail-loud" tabindex="-1">5. 方法論誠實校準（守 R12 Fail Loud） <a class="header-anchor" href="#_5-方法論誠實校準-守-r12-fail-loud" aria-label="Permalink to &quot;5. 方法論誠實校準（守 R12 Fail Loud）&quot;">​</a></h2><ul><li><strong>未推翻任何既有結論</strong>：13 gap 全是補強，不改報告裁決。誠實標明本次「邊際價值在補量化接地，非主張翻新」。</li><li><strong>同源/語意去重 2 條</strong>（ETH-138 / 35:1）：grep-verify 只驗「字串不在報告」，<strong>不驗語意是否已被別篇講過</strong>——此盲點由 advisor 攔截，補語意重複檢查後正確標同源/掛既有段（MEMORY 新 Lesson 候選）。</li><li><strong>黑名單數字防誤植</strong>：報告內所有易混百分比（−82.6% KV cost vs −82.3% latency / 35:1 vs 33.4-35.2pp / 1.0-1.35× tokenizer / 57% Overthinking）均配 verbatim + 行號 + ⚠️ 適用範圍註記。</li><li><strong>scope 守紀</strong>：10 篇 defer/reject 未強塞（HeavySkill/Life-Harness 親驗屬實仍因 scope 記 ledger 不落報告）。</li></ul><hr><p><em>合併日期：2026-06-05 | 來源：5 報告 in-place 更新 + 76 篇近期 corpus gap-vote | 13 confirmed gap（含 2 同源/語意去重標注）| 全數主對話親自 grep 接地 | gap-vote 三技能共識（research-hub/overnight-research/autoresearch:reason）</em></p>',40)])])}const u=e(o,[["render",s]]);export{p as __pageData,u as default};
